def _slope_expr(columns: Sequence[str]) -> pl.Expr:
    weights = (-1.0 / 7.0, -3.0 / 35.0, -1.0 / 35.0, 1.0 / 35.0, 3.0 / 35.0, 1.0 / 7.0)
